// Generated by scripts/util-pages.mjs — runs in a module Worker (see util/worker.js)
import { fmtTime } from '/util/util.js'
const load = u => import(u).catch(() => new Promise(r => setTimeout(r, 300)).then(() => import(u)))
const separateLib = import('/util/vendor/neural-separate.js?v=01f863b5')
const NAMES = {"scnet":"SCNet","scnet-large":"SCNet-large","mel-roformer":"Mel-Band RoFormer"}

// (a model may fetch two files at once: Mel-RoFormer's engine its .json beside its .bin, so the bytes are summed)
